<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';$user=require_login();$stats=['carros'=>0,'mes'=>0,'preventivas'=>0,'correctivas'=>0];$recentes=[];$ultima=null;$dbError='';
try{$stats['carros']=(int)db()->query('SELECT COUNT(*) FROM carros WHERE activo=1')->fetchColumn();$m=db()->query("SELECT COUNT(*) total,SUM(tipo='Preventiva') preventivas,SUM(tipo='Correctiva') correctivas FROM mantenciones WHERE realizada_en>=DATE_FORMAT(CURRENT_DATE(),'%Y-%m-01') AND realizada_en<DATE_FORMAT(DATE_ADD(CURRENT_DATE(),INTERVAL 1 MONTH),'%Y-%m-01')")->fetch()?:[];$stats['mes']=(int)($m['total']??0);$stats['preventivas']=(int)($m['preventivas']??0);$stats['correctivas']=(int)($m['correctivas']??0);$ultima=db()->query('SELECT m.realizada_en,c.codigo FROM mantenciones m JOIN carros c ON c.id=m.carro_id ORDER BY m.realizada_en DESC,m.id DESC LIMIT 1')->fetch()?:null;$recentes=db()->query('SELECT m.tipo,m.realizada_en,c.codigo,u.nombre trabajador FROM mantenciones m JOIN carros c ON c.id=m.carro_id JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.realizada_en DESC,m.id DESC LIMIT 8')->fetchAll();}catch(PDOException $ex){$dbError='No se pudieron cargar los indicadores. Verifica la conexión con la base de datos.';}
function icon(string $name):string{$i=['home'=>'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1V10Z"/>','edit'=>'<path d="m4 20 4.5-1L19 8.5a2.1 2.1 0 0 0-3-3L5.5 16 4 20Z"/><path d="m14.5 7.5 3 3"/>','scan'=>'<path d="M4 8V5a1 1 0 0 1 1-1h3M16 4h3a1 1 0 0 1 1 1v3M20 16v3a1 1 0 0 1-1 1h-3M8 20H5a1 1 0 0 1-1-1v-3"/><path d="M8 12h8M12 8v8"/>','history'=>'<path d="M4 12a8 8 0 1 0 2.3-5.7L4 8.5"/><path d="M4 4v4.5h4.5M12 8v4l2.5 1.5"/>','fleet'=>'<path d="M4 16V7l2-3h12l2 3v9M4 16h16M7 19h2M15 19h2M7 12h10"/>','qr'=>'<path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h2v2h-2zM18 18h2v2h-2zM18 14h2v2h-2z"/>','report'=>'<path d="M4 19V5M4 19h17M8 16v-5M12 16V8M16 16V4M20 16v-8"/>'];return '<svg viewBox="0 0 24 24" aria-hidden="true">'.$i[$name].'</svg>';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel de mantenciones</title><link rel="stylesheet" href="assets/css/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="panel.php"><span class="brand-mark">Q</span><span>QLC</span></a><nav aria-label="Navegación principal"><a class="nav-item active" href="panel.php"><?=icon('home')?>Escritorio</a><a class="nav-item" href="index.php"><?=icon('edit')?>Registrar mantención</a><a class="nav-item" href="escanear.php"><?=icon('scan')?>Escanear QR</a><a class="nav-item" href="historial.php"><?=icon('history')?>Ver historial</a><?php if($user['rol']==='supervisor'):?><a class="nav-item" href="carros.php"><?=icon('fleet')?>Administrar carros</a><a class="nav-item" href="generar_qr.php"><?=icon('qr')?>Códigos QR</a><?php endif;?></nav><div class="side-footer"><span class="status-dot"></span>Sistema operativo</div></aside><main class="main-content"><header class="topbar"><button class="menu-button" type="button" aria-label="Mostrar navegación" onclick="document.body.classList.toggle('menu-open')">☰</button><div class="top-user"><span class="avatar"><?=e(strtoupper(substr($user['nombre'],0,1)))?></span><span>Hola, <?=e($user['nombre'])?> <small>(<?=e(ucfirst($user['rol']))?>)</small></span><a href="logout.php">Cerrar sesión</a></div></header><div class="content-wrap"><div class="heading"><p class="eyebrow">Escritorio</p><h1>Panel de mantenciones</h1><p class="lead">Control y seguimiento de la flota ferroviaria.</p></div><?php if($dbError):?><div class="alert" role="alert"><?=e($dbError)?></div><?php endif;?><section class="metrics" aria-label="Indicadores del sistema"><article class="metric"><span class="metric-icon teal"><?=icon('fleet')?></span><div><span>Carros activos</span><strong><?=number_format($stats['carros'],0,',','.')?></strong><small>Registrados en el sistema</small></div></article><article class="metric"><span class="metric-icon blue"><?=icon('history')?></span><div><span>Mantenciones este mes</span><strong><?=number_format($stats['mes'],0,',','.')?></strong><small>Desde el primer día del mes</small></div></article><article class="metric"><span class="metric-icon green"><?=icon('edit')?></span><div><span>Preventivas</span><strong><?=number_format($stats['preventivas'],0,',','.')?></strong><small>Este mes</small></div></article><article class="metric"><span class="metric-icon amber"><?=icon('report')?></span><div><span>Correctivas</span><strong><?=number_format($stats['correctivas'],0,',','.')?></strong><small>Este mes</small></div></article><article class="metric latest"><div><span>Última mantención</span><strong><?= $ultima?e(date('d/m',strtotime($ultima['realizada_en']))):'—' ?></strong><small><?= $ultima?'Carro '.e($ultima['codigo']):'Sin registros todavía' ?></small></div></article></section><h2 class="section-title">Acciones principales</h2><section class="action-grid"><a class="action-card" href="index.php"><span class="card-icon teal"><?=icon('edit')?></span><h3>Registrar mantención</h3><p>Ingresar un trabajo realizado y adjuntar una foto.</p><span class="card-link">Nueva mantención →</span></a><a class="action-card" href="escanear.php"><span class="card-icon purple"><?=icon('scan')?></span><h3>Escanear carros</h3><p>Consultar el historial usando la cámara del teléfono.</p><span class="card-link">Iniciar escáner →</span></a><a class="action-card" href="historial.php"><span class="card-icon peach"><?=icon('history')?></span><h3>Ver historial</h3><p>Seleccionar un carro y consultar sus mantenciones.</p><span class="card-link">Buscar historial →</span></a><?php if($user['rol']==='supervisor'):?><a class="action-card" href="generar_qr.php"><span class="card-icon mint"><?=icon('qr')?></span><h3>Códigos QR</h3><p>Descargar o imprimir el QR de cada carro.</p><span class="card-link">Gestionar códigos →</span></a><a class="action-card" href="carros.php"><span class="card-icon gold"><?=icon('fleet')?></span><h3>Gestión de flota</h3><p>Agregar, modificar y revisar los carros activos.</p><span class="card-link">Administrar carros →</span></a><article class="action-card report-card"><span class="card-icon chart"><?=icon('report')?></span><h3>Reportes y analíticas</h3><p>Resumen operativo basado en los registros actuales.</p><span class="card-note">Próximamente</span></article><?php endif;?></section><section class="recent" aria-labelledby="recent-title"><div class="recent-header"><div><p class="eyebrow">Seguimiento</p><h2 id="recent-title">Actividad reciente</h2></div><a href="historial.php">Ver todos los historiales →</a></div><?php if(!$recentes):?><div class="empty">Todavía no hay mantenciones registradas.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Carro</th><th>Tipo</th><th>Trabajador</th><th>Fecha</th><th></th></tr></thead><tbody><?php foreach($recentes as $item):?><tr><td data-label="Carro"><strong><?=e($item['codigo'])?></strong></td><td data-label="Tipo"><span class="type <?=strtolower($item['tipo'])?>"><?=e($item['tipo'])?></span></td><td data-label="Trabajador"><?=e($item['trabajador'])?></td><td data-label="Fecha"><?=e(date('d/m/Y H:i',strtotime($item['realizada_en'])))?></td><td><a class="table-link" href="historial.php?carro=<?=rawurlencode($item['codigo'])?>">Ver historial</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main></div></body></html>
